{
  "mechanisms": [
    {
      "name": "mb_mf_mixture",
      "title": "MB/MF Mixture Weight",
      "description": "Weights the contribution of model-based and model-free values to determine Stage 1 choice probabilities.",
      "params": [
        {
          "name": "w",
          "bounds": [
            0,
            1
          ]
        }
      ],
      "evidence": "q_net_1 = w * q_stage1_mb + (1 - w) * q_stage1_mf",
      "expressible_in_slots": true
    },
    {
      "name": "choice_stickiness",
      "title": "Choice Stickiness",
      "description": "Adds a scalar bonus to the Stage 1 logit of the action chosen on the previous trial to capture perseveration.",
      "params": [
        {
          "name": "stick",
          "bounds": [
            0,
            5
          ]
        }
      ],
      "evidence": "if last_action_1 != -1:\n            logits_1[last_action_1] += stick",
      "expressible_in_slots": true
    },
    {
      "name": "eligibility_trace",
      "title": "Eligibility Trace",
      "description": "Updates the Stage 1 model-free value using the Stage 2 reward prediction error, scaled by an eligibility trace parameter.",
      "params": [
        {
          "name": "lam",
          "bounds": [
            0,
            1
          ]
        }
      ],
      "evidence": "q_stage1_mf[a1] += lr * delta_stage1 + lr * lam * delta_stage2",
      "expressible_in_slots": true
    },
    {
      "name": "counterfactual_update",
      "title": "Counterfactual Update",
      "description": "Updates the value of the unchosen Stage 2 option in the opposite direction of the received reward, reflecting a belief in anti-correlated rewards.",
      "params": [
        {
          "name": "lr_cf",
          "bounds": [
            0,
            1
          ]
        }
      ],
      "evidence": "unchosen_a2 = 1 - a2\n            delta_cf = (1.0 - r) - q_stage2_mf[state_idx, unchosen_a2]\n            q_stage2_mf[state_idx, unchosen_a2] += lr_cf * delta_cf",
      "expressible_in_slots": true
    }
  ]
}
